$(()=>{$(".btn-list").click((function(){$(".res-prod-list").addClass("prod-list-view")})),$(".btn-grid").click((function(){$(".res-prod-list").removeClass("prod-list-view")})),$('.results-tabs a[data-toggle="tab"]').on("show.bs.tab",e=>{$(e.target).attr("id")===$(".adv-prod-slider").data("show")?$(".adv-prod-slider").slideDown():$(".adv-prod-slider").slideUp()})});